import re
import time
from abc import abstractmethod

from taf.transport.ssh.connection import SSHConnection

from taf.hw.pdu.devices.base import PDU
from taf.hw.pdu.exceptions import SshReceivedStatusInvalid


class SshConnection(PDU):
    TIME_BUFFER = 2

    def __init__(self, host, login, password, port):
        super(SshConnection, self).__init__(host)
        self.ssh = SSHConnection()
        parameters = {
            "hostname": host,
            "username": login,
            "password": password,
            "port": port,
        }
        self.ssh.configure(**parameters)

    def send_cmd_and_return_response(self, cmd):
        self.ssh.connect()
        channel = self.ssh.invoke_shell()
        channel.send(cmd)
        time.sleep(self.TIME_BUFFER)
        received_msg = str(channel.recv(999))
        try:
            re.search(cmd.rstrip("\n"), received_msg).group(0)
        except BaseException:
            exc_msg = f"Command sent but fail with response {received_msg}."
            raise SshReceivedStatusInvalid(exc_msg)
        channel.close()
        return received_msg

    def execute_command(self, cmd):
        self.ssh.connect()
        try:
            result = self.ssh.execute(cmd)
            result = result.rstrip()
        except BaseException as exc:
            raise SshReceivedStatusInvalid(f"Command '{cmd}' execution failed with error: {exc}")
        finally:
            self.ssh.disconnect()
        return result

    @abstractmethod
    def power_on(self, port):
        """Build command for power_on based PDU"""

    @abstractmethod
    def power_off(self, port):
        """Build command for power_off based PDU"""

    @abstractmethod
    def get_port_status(self, port):
        """Build command for get_port_status basedPDU"""

    def _set_port_status(self, port, status):
        """Not implemented due to not supported get_port_status"""

    def _port_setting(self):
        """Not implemented due to not supported get_port_status"""
